CREATE PROCEDURE {{SCHEMA}}.{{PROCEDURE}}
  (IN P_FLAG INTEGER, OUT P_TEXT VARCHAR(64))
  VERSION V1
  LANGUAGE SQL
  SPECIFIC {{SCHEMA}}.{{PROCEDURE}}
  {{DETERMINISM}}
  {{ACCESS}}
  CALLED ON NULL INPUT
  PARAMETER CCSID UNICODE
  DYNAMIC RESULT SETS 0
  COMMIT ON RETURN NO
  DISABLE DEBUG MODE
  APPLCOMPAT {{APPLCOMPAT}}
  {{BODY}}

multiline.sql:
BEGIN
  DECLARE V_TEXT VARCHAR(64) DEFAULT '  MiXeD; ''quoted''  tail ';
  IF P_FLAG = 1 THEN
    SET P_TEXT = V_TEXT;
  ELSE
    SET P_TEXT = 'other';
  END IF;
END

